			/**
			 * 상세 페이지 CRUD 권한 처리 
			 * @param {"CREATE" | "READ" | "UPDATE"} psType CRUD Type
			 */
			function setDtlCrud(psType) {
			    
			    if (psType == "READ") {
			        
			        util.Control.setReadOnly(app, true , ["grpData"]);
			        util.Control.setReadOnly(app, true , ["grpCaseTrprList"]);
			        util.Control.setVisible (app, false, ["btnSave", "btnRestore"]);
			        
			        // util.Control.setVisible (app, true , ["btnUpdate", "btnDelete"]);
			        util.Control.setEnable  (app, false, ["btnCallPlanHstr", "btnCallExcnHstr"]);

			        app.lookup("dsCaseTrprList").clearFilter();

			        msCrudType = "READ";

			    } else {
			        
			        if (psType == "CREATE") {
			            app.lookup("dsDetailInfo")  .clear();
			            app.lookup("dsCaseTrprList").clear();
			            app.lookup("dsProgramList") .clear();

			            app.lookup("dsDetailInfo").insertRow(0);
			            app.lookup("dsDetailInfo").setValue(0, "PIC_NO"                     , sUserNo);
			            app.lookup("dsDetailInfo").setValue(0, "PIC_NM"                     , sUserNm);
			            app.lookup("dsDetailInfo").setValue(0, "TKCG_INST_NO"               , sInstNo);
			            app.lookup("dsDetailInfo").setValue(0, "TKCG_INST_NM"               , sInstNm);
			            app.lookup("dsDetailInfo").setValue(0, "SRVC_EXCN_BIZ_CHC_PSBLTY_YN", sSrvcExcnBizChcPsbltyYn);
			            app.lookup("dsDetailInfo").setValue(0, "SRVC_GR_PVSN_YN"            , "Y");
			            
			            msCrudType = "CREATE";
			            
			        } else if (psType == "UPDATE") {            
			            msCrudType = "UPDATE";
			        }
			                
			        util.Control.setReadOnly(app, false, ["grpData"]);
			        util.Control.setReadOnly(app, false, ["grpCaseTrprList"]);
			        util.Control.setVisible (app, true , ["btnSave", "btnRestore"]);
			        util.Control.setVisible (app, false, ["btnUpdate", "btnDelete"]);
			        
			        util.Control.setEnable  (app, true , ["btnCallPlanHstr", "btnCallExcnHstr"]);
			    }
			    
			    util.Control.redraw(app, "grpData");
			    util.Control.redraw(app, "grpCaseTrprList");
			    
			}

