			            sResrceNo = app.lookup("dsDetailInfo").getValue(0, "RESRCE_NO"); //자원번호
			            app.lookup("dmParam").setValue("RESRCE_NO", sResrceNo);
			            //사례대상자조회 서브미션 호출
			            app.lookup("dsCaseTrprList").clear();
