			/*
			 * "원스크린" 버튼(btn2)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtn2Click(e){

			    var btn2 = e.control;

			    var selIdx = app.lookup("grdCaseTrprList").getSelectedRowIndex();
			    if(selIdx < 0) {
			        util.Msg.alert(app, "대상자를 선택해주세요.");
			        return false;
			    }

			    var sendValue = {"TRPR_INFO_NO" : util.Grid.getCellValue(app, "grdCaseTrprList", "TRPR_INFO_NO", selIdx)};

			    util.Dialog.open(app, "app/itgcm/pop/itgcm_sc_pop_008", "원스크린", 1200, 760, function() {}, sendValue);
			    
			}

			/*
			 * "저장" 버튼(btnSave)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnSaveClick(e){
			    // 프리폼 필수값 유효성 체크 (저장 confirm 전에 체크)
			    if (!util.validate(app, "grpSrvcGrPvsnInfo")) return false; // 실행상세

			    if (ValueUtil.isNull(app.lookup("txaSrvcPvsnCn").value)) {
			        util.Msg.alert(app, "서비스제공내용은(는) 필수 입력 항목입니다.", "", function(e) {
			            app.lookup("txaSrvcPvsnCn").focus();
			        });

			        return false;
			    }

			    var sSrvcExcnBizNo = app.lookup("dsDetailInfo").getValue(0, "SRVC_EXCN_BIZ_NO"); //서비스실행사업번호
			    var sSrvcExcnBizNm = app.lookup("dsDetailInfo").getValue(0, "SRVC_EXCN_BIZ_NM"); //서비스실행사업명

			    if(sSrvcExcnBizChcPsbltyYn == "Y") {
			        if(ValueUtil.isNull(sSrvcExcnBizNo) || ValueUtil.isNull(sSrvcExcnBizNm)) {
			            util.Msg.alert(app, "서비스실행사업을 선택해주십시요.");
			            return false;
			        }
			    }

			    // 미지원/삭제 코드 선택 확인
			    var bFlag = true;
			    var sMsg  = "";

			    var comList = AppUtil.getComponentList(app, "grpData", ["combobox","radiobutton"]);
			    for(var i=0; i<comList.length; i++) {
			        var comObj = comList[i];

			        var sText       = comObj.text;
			        var sFiledLabel = comObj.fieldLabel;

			        if(comObj.enabled && !comObj.readonly) {
			            if(sText.indexOf('삭제') > -1 || sText.indexOf('미지원') > -1) {
			                bFlag = false;

			                if(ValueUtil.isNull(sMsg)) {
			                    sMsg = sFiledLabel + "을(를) 확인해 주세요.";
			                } else {
			                    sMsg = sMsg + "\n" + sFiledLabel + "을(를) 확인해 주세요.";
			                }
			            }
			        }
			    }
			    
			    if(untTaskwk == "U03"){
			        var dsDetailInfo = app.lookup("dsDetailInfo");
			        var srtDt = dsDetailInfo.getValue(0, "SRVC_PVSN_BGNG_YMD");
			        var endDt = dsDetailInfo.getValue(0, "SRVC_PVSN_END_YMD");
			        if(ValueUtil.fixNumber(endDt) - ValueUtil.fixNumber(srtDt) > 9999){
			            util.Msg.alert(app, "자원제공기간은 최장 1년 까지만 입력이 가능 합니다.");
			            return false;
			        }
			    }
			    
			    if(!bFlag) {
			        util.Msg.alert(app, sMsg);
			        return false;
			    }

			    var dsCaseTrprList = app.lookup("dsCaseTrprList");
			    if(dsCaseTrprList.getRowCount() == 0) {
			        util.Msg.alert(app, "대상자목록을 입력해주십시요.");
			        return false;
			    } else {
			        if(dsCaseTrprList.getRowCount() == dsCaseTrprList.getRowStatedCount(cpr.data.tabledata.RowState.DELETED)) {
			            util.Msg.alert(app, "대상자목록을 입력해주십시요.");
			            return false;
			        }            
			    }

			    if (!util.validate(app, "grpCaseTrprList")) return false; // 대상자 목록
			    
			    /* 사례대상자명 입력 후 저장가능 유효성 체크 추가 (사례관리번호 null 방지)*/
			    for(var i=0; i<dsCaseTrprList.getRowCount(); i++){
			        var caseMngNo = dsCaseTrprList.getValue(i, "CASE_MNG_NO");
			        if(caseMngNo == '' || caseMngNo == null){
			            var trprNm = dsCaseTrprList.getValue(i, "TRPR_NM");
			            
			            util.Msg.alert(app, ( trprNm + " 사례대상자명은 사례대상자 검색목록에서 선택되지 않았습니다.\n 사례대상자 팝업에서 대상자를 선택 후 저장을 해주시기 바랍니다."), null, function(){
			                
			            }, "사례대상자목록");            
			            return false;
			        }
			    }

			    var sEndDate = app.lookup("cmnDaterangePicker1").endDate;

			    var sMsg      = "";
			    var bCheckVal = true;

			    for(var i=0; i<dsCaseTrprList.getRowCount(); i++) {
			        var nRowType     = dsCaseTrprList.getRowState(i);

			        var sDdlnYm      = dsCaseTrprList.getValue(i, "DDLN_YM");       //마감년월
			        var sDdlnCrtrYmd = dsCaseTrprList.getValue(i, "DDLN_CRTR_YMD"); //마감기준년월
			        var sCaseTrmnYmd = dsCaseTrprList.getValue(i, "CASE_TRMN_YMD"); //사례종결일자

			        if(!ValueUtil.isNull(sCaseTrmnYmd)) {
			            if(nRowType == cpr.data.tabledata.RowState.DELETED || nRowType == cpr.data.tabledata.RowState.INSERTED) {
			                var sRowTypeNm = "";
			                if(nRowType == cpr.data.tabledata.RowState.DELETED) {
			                    sRowTypeNm = "삭제";
			                } else {
			                    sRowTypeNm = "등록";
			                }

			                if(ValueUtil.isNull(sMsg)) {
			                    sMsg = (i+1) + "번째 대상자(" + dsCaseTrprList.getValue(i, "TRPR_NM") + ")의 사례가 종결되어 " + sRowTypeNm + "이(가) 불가능합니다.";
			                } else {
			                    sMsg = sMsg + "\n" + (i+1) + "번째 대상자(" + dsCaseTrprList.getValue(i, "TRPR_NM") + ")의 사례가 종결되어 " + sRowTypeNm + "이(가) 불가능합니다.";
			                }
			            }
			        } else {
			            if(!ValueUtil.isNull(sDdlnCrtrYmd)) {
			                //1.마감기준일자 vs 당일 비교
			                if(sDdlnCrtrYmd > vsToday) {
			                    if(sEndDate.substring(0,6) < sDdlnYm) {
			                        if(ValueUtil.isNull(sMsg)) {
			                            sMsg = (i+1) + "번째 대상자(" + dsCaseTrprList.getValue(i, "TRPR_NM") + ")";
			                        } else {
			                            sMsg = sMsg + "\n" + (i+1) + "번째 대상자(" + dsCaseTrprList.getValue(i, "TRPR_NM") + ")";
			                        }

			                        bCheckVal = false;
			                    }
			                } else {
			                    if(sEndDate.substring(0,6) <= sDdlnYm) {
			                        if(ValueUtil.isNull(sMsg)) {
			                            sMsg = (i+1) + "번째 대상자(" + dsCaseTrprList.getValue(i, "TRPR_NM") + ")";
			                        } else {
			                            sMsg = sMsg + "\n" + (i+1) + "번째 대상자(" + dsCaseTrprList.getValue(i, "TRPR_NM") + ")";
			                        }

			                        bCheckVal = false;
			                    }
			                }

			                if(!bCheckVal) {
			                    if(nRowType == cpr.data.tabledata.RowState.DELETED) {
			                        sMsg = sMsg + "의 월마감이 완료되어 삭제가 불가능합니다.";
			                    } else {
			                        sMsg = sMsg + "의 마감년월을 확인하시기 바랍니다.";
			                    }
			                }
			            }    
			        }
			    }
			    if(!ValueUtil.isNull(sMsg)) {
			        util.Msg.alert(app, sMsg);
			        return false;
			    }

			    var dsExcnSrvcBizClList = app.lookup("dsExcnSrvcBizClList");
			    for(var i = 0; i < dsExcnSrvcBizClList.getRowCount(); i++){
			        var excnDetaiaBizNo = dsExcnSrvcBizClList.getValue(i, "EXCN_SRVC_DETAIA_BIZ_NO");
			        if(ValueUtil.isNull(excnDetaiaBizNo)){
			            util.Msg.alert(app, "실행서비스 사업분류 목록에서\n실행서비스 세부사업명을 선택해주십시요.");
			            return false;
			        }
			    }

			    if(app.lookup("dsDetailInfo").getValue(0, "SRVC_TYPE_SE_CD") == "04") {
			        if(untTaskwk == 'U09' || untTaskwk == 'U10'){
			            if (!util.validate(app, "grpSrvcGrPvsnProgMainList")) return false; // 프로그램 목록
			        }
			    } 
			    
			    for(var i = 0; i < dsExcnSrvcBizClList.getRowCount(); i++){
			        if(ValueUtil.isNull(dsExcnSrvcBizClList.getValue(i, "RESRCE_NO"))){
			            dsExcnSrvcBizClList.setValue(i, "RESRCE_NO", app.lookup("dsDetailInfo").getValue(0, "RESRCE_NO"));    
			        }
			    }
			    
			    app.lookup("dmParam").clear();

			    //첨부파일 저장 실행
			    var objMultifileupload = app.lookup("cmnMultifileupload"); //첨부파일
			    objMultifileupload.send(function(){

			        if(objMultifileupload.getFileList().length == 0) {
			            app.lookup("dsDetailInfo").setValue(0, "ATFINO", "");
			        }

			        //저장이벤트 실행
			        util.Submit.send(app, "subSrvcGrPvsnSave", function(pbSuccess){
			            if(pbSuccess){
			                util.Msg.alert(app, "저장 되었습니다.");

			                setDtlCrud("READ");
			                app.lookup("dmParam").setValue("UNT_TASKWK_SE_CD", untTaskwk);

			                doList("save");
			            }
			        });        
			    });
			}

