			/*
			 * "삭제" 버튼(btnDelete)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnDeleteClick(e){

			    var sMsg      = "";
			    var bCheckVal = true;

			    var dsCaseTrprList = app.lookup("dsCaseTrprList");

			    var sEndDate = app.lookup("cmnDaterangePicker1").endDate;

			    for(var i=0; i<dsCaseTrprList.getRowCount(); i++) {
			        var sDdlnYm      = dsCaseTrprList.getValue(i, "DDLN_YM");       //마감년월
			        var sDdlnCrtrYmd = dsCaseTrprList.getValue(i, "DDLN_CRTR_YMD"); //마감기준년월
			        var sCaseTrmnYmd = dsCaseTrprList.getValue(i, "CASE_TRMN_YMD"); //사례종결일자

			        if(!ValueUtil.isNull(sCaseTrmnYmd)) {
			            if(ValueUtil.isNull(sMsg)) {
			                sMsg = (i+1) + "번째 대상자(" + dsCaseTrprList.getValue(i, "TRPR_NM") + ")의 사례가 종결되어 삭제가 불가능합니다.";
			            } else {
			                sMsg = sMsg + "\n" + (i+1) + "번째 대상자(" + dsCaseTrprList.getValue(i, "TRPR_NM") + ")의 사례가 종결되어 삭제가 불가능합니다.";
			            }
			        } else {
			            //1.마감기준일자 vs 당일 비교
			            if(sDdlnCrtrYmd > vsToday) {
			                if(sEndDate.substring(0,6) < sDdlnYm) {
			                    if(ValueUtil.isNull(sMsg)) {
			                        sMsg = (i+1) + "번째 대상자(" + dsCaseTrprList.getValue(i, "TRPR_NM") + ")";
			                    } else {
			                        sMsg = sMsg + "\n" + (i+1) + "번째 대상자(" + dsCaseTrprList.getValue(i, "TRPR_NM") + ")";
			                    }

			                    bCheckVal = false;
			                }
			            } else {
			                if(sEndDate.substring(0,6) <= sDdlnYm) {
			                    if(ValueUtil.isNull(sMsg)) {
			                        sMsg = (i+1) + "번째 대상자(" + dsCaseTrprList.getValue(i, "TRPR_NM") + ")";
			                    } else {
			                        sMsg = sMsg + "\n" + (i+1) + "번째 대상자(" + dsCaseTrprList.getValue(i, "TRPR_NM") + ")";
			                    }

			                    bCheckVal = false;
			                }
			            }
			            
			            if(!bCheckVal) {
			                sMsg = sMsg + "의 월마감이 완료되어 삭제가 불가능합니다.";
			            }
			        }
			    }
			    if(!ValueUtil.isNull(sMsg)) {
			        util.Msg.alert(app, sMsg);
			        return false;
			    }

			    util.Msg.confirm(app, "CRM-M002", null, function() {
			        app.lookup("dsDetailInfo")  .setRowStateAll(cpr.data.tabledata.RowState.DELETED);
			        app.lookup("dsCaseTrprList").setRowStateAll(cpr.data.tabledata.RowState.DELETED);
			        
			        if(app.lookup("dsDetailInfo").getValue(0, "SRVC_TYPE_SE_CD") == "04") {
			            if(app.lookup("dsProgramList").getRowCount() > 0) {
			                app.lookup("dsProgramList").setRowStateAll(cpr.data.tabledata.RowState.DELETED);
			            }
			        }

			        util.Submit.send(app, "subSrvcGrPvsnDelete", function(pbSuccess){
			            if(pbSuccess){
			                util.Msg.alert(app, "INF-M000", "삭제 되었습니다.", function() {
			                    if(typeof rtnVal == "function") {
			                        rtnVal();
			                    }

			                    /** @type cpr.controls.MDIFolder */
			                    var mdiCn = app.getRootAppInstance().lookup("mdiCn");
			                    var appId = app.id;
			                    if(appId.indexOf("$") > -1) {
			                        appId = appId.substring(0, appId.lastIndexOf("$"));
			                    }

			                    var vcFindItem = mdiCn.findItemWithAppID(appId);
			                    mdiCn.close(vcFindItem);
			                });
			            }
			        });
			    }, function() {
			        // 취소 동작
			        return false;
			    }, "삭제확인");
			}

			/*
			 * "취소" 버튼(btnRestore)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnRestoreClick(e){

			    //사례대상자목록 Dataset 수정전 상태로 원복 
			    var dsCaseTrprList = app.lookup("dsCaseTrprList");
			    var dsProgramList  = app.lookup("dsProgramList");
			    var dsDetailInfo   = app.lookup("dsDetailInfo");

			    if (util.Grid.isModified(app, "grdCaseTrprList", "CRM", function() {
			        // 확인 동작
			        dsCaseTrprList.revert();
			        dsProgramList .revert();
			        dsDetailInfo  .revert();

			        if(msCrudType != "CREATE") {
			            setDtlCrud("READ");
			        } else {
			            setDtlCrud("CREATE");
			        }

			        // 데이터를 복원하고 취소, 목록 등 기능처리
			        setDsCaseTrprRowCnt();
			        setDsProgramRowCnt();

			    }, function() {
			        // 취소 동작
			    })) return false;

			    else {
			        dsCaseTrprList.revert();
			        dsProgramList .revert();
			        dsDetailInfo  .revert();

			        if(msCrudType != "CREATE") {
			            setDtlCrud("READ");
			        } else {
			            setDtlCrud("CREATE");
			        }

			        setDsCaseTrprRowCnt();
			        setDsProgramRowCnt();      
			    }
			}

