			function onCmbPvsnServiceTypeSelectionChange(e){
			    
			    var cmbPvsnServiceType = app.lookup("cmbPvsnServiceType");
			    var vsSeltVal          = cmbPvsnServiceType.value;  
			    var resrceLclas    = app.lookup("dsDetailInfo").getValue(0, "SRVC_RESRCE_LCLAS_SE_CD");
			    
			    if(ValueUtil.isNull(vsSeltVal)) return false;
			    
			    // 서비스 유형이 프로그램일 경우
			    // 2023.04.11[응용3팀-이상훈] 프로그램(SRVC_TYPE_SE_CD:"04") 중 상담자원(SRVC_RESRCE_LCLAS_SE_CD:"01") 제외
			    if (vsSeltVal == "04" && resrceLclas != "01") {
			        /* 2023-03-22 사례계획과일괄등록과 집단서비스등록에서 u09, u10 일때만 프로그램이 표시되도록 함*/        
			        if(untTaskwk == 'U09' || untTaskwk == 'U10'){        
			            util.Control.setVisible(app, true, "grpSrvcGrPvsnProgMainList");
			            onProgramList();
			        } else {
			            util.Control.setVisible(app, false, "grpSrvcGrPvsnProgMainList");
			            util.DataSet.clear(app, "dsProgramList");
			        }
			    } else {
			        util.Control.setVisible(app, false, "grpSrvcGrPvsnProgMainList");
			        util.DataSet.clear(app, "dsProgramList");
			    }
			}

