			/*
			 * 사용자 정의 컨트롤에서 range-before-value-change 이벤트 발생 시 호출.
			 * 기간선택 컴포넌트 before-value-change 이벤트 (e.userData["startDate"], e.userData["endDate"])
			 */
			function onCmnDaterangePicker1RangeBeforeValueChange(e){

			    var cmnDaterangePicker1 = e.control;

			    var sEndDate = e.userData["endDate"];

			    var sMsg      = "대상자목록의 ";
			    var bCheckVal = true;

			    var dsCaseTrprList = app.lookup("dsCaseTrprList");
			    for(var i=0; i<dsCaseTrprList.getRowCount(); i++) {
			        if(dsCaseTrprList.getRowState(i) == cpr.data.tabledata.RowState.DELETED) {
			            continue;
			        }

			        var sDdlnYm      = dsCaseTrprList.getValue(i, "DDLN_YM");       //마감년월
			        var sDdlnCrtrYmd = dsCaseTrprList.getValue(i, "DDLN_CRTR_YMD"); //마감기준년월
			        var sCaseTrmnYmd = dsCaseTrprList.getValue(i, "CASE_TRMN_YMD"); //사례종결일자

			        if(!ValueUtil.isNull(sCaseTrmnYmd)) {
			            sMsg = sMsg + (i+1) + "번째 대상자(" + dsCaseTrprList.getValue(i, "TRPR_NM") + ")의 사례가 종결되어 등록이 불가능합니다.";
			            util.Msg.alert(app, sMsg);
			            return false;
			        } else {
			            if(!ValueUtil.isNull(sEndDate)) {
			                if(!ValueUtil.isNull(sDdlnCrtrYmd)) {
			                    //1.마감기준일자 vs 당일 비교
			                    if(sDdlnCrtrYmd > vsToday) {
			                        if(sEndDate.substring(0,6) < sDdlnYm) {
			                            sMsg = sMsg + "\n" + (i+1) + "번째 대상자(" + dsCaseTrprList.getValue(i, "TRPR_NM") + ")";
			        
			                            bCheckVal = false;
			                        }
			                    } else {
			                        if(sEndDate.substring(0,6) <= sDdlnYm) {
			                            sMsg = sMsg + "\n" + (i+1) + "번째 대상자(" + dsCaseTrprList.getValue(i, "TRPR_NM") + ")";
			        
			                            bCheckVal = false;
			                        }
			                    }
			                }
			            }
			        }
			    }

			    if(!bCheckVal) {
			        sMsg = sMsg + "\n마감년월을 확인하시기 바랍니다.";
			        util.Msg.alert(app, sMsg);
			        return false;
			    }
			}

			/*
			 * 사용자 정의 컨트롤에서 beforeDelete 이벤트 발생 시 호출.
			 * 삭제버튼 클릭전 호출 이벤트(행 삭제전에 체크할 비지니스 로직이 있는 경우 사용)
			 */
			function onComGridBtn3BeforeDelete3(e){

			    var comGridBtn3 = e.control;

			    var bCheckVal = true;
			    var sEndDate  = app.lookup("cmnDaterangePicker1").endDate;

			    var nIdx = util.Grid.getIndex(app, "grdCaseTrprList");

			    var sDdlnYm      = util.Grid.getCellValue(app, "grdCaseTrprList", "DDLN_YM"      , nIdx);
			    var sDdlnCrtrYmd = util.Grid.getCellValue(app, "grdCaseTrprList", "DDLN_CRTR_YMD", nIdx);
			    var sCaseTrmnYmd = util.Grid.getCellValue(app, "grdCaseTrprList", "CASE_TRMN_YMD", nIdx);

			    var sRowType     = util.Grid.getRowState(app, "grdCaseTrprList", nIdx);

			    if(!ValueUtil.isNull(sCaseTrmnYmd)) {
			        if(sRowType != cpr.data.tabledata.RowState.INSERTED) {
			            util.Msg.alert(app, "선택 대상자의 사례가 종결되어 삭제가 불가능합니다.");
			            return false;
			        }
			    } else {
			        if(!ValueUtil.isNull(sEndDate)) {
			            if(!ValueUtil.isNull(sDdlnCrtrYmd)) {
			                //1.마감기준일자 vs 당일 비교
			                if(sDdlnCrtrYmd > vsToday) {
			                    if(sEndDate.substring(0,6) < sDdlnYm) {
			                        bCheckVal = false;
			                    }
			                } else {
			                    if(sEndDate.substring(0,6) <= sDdlnYm) {
			                        bCheckVal = false;
			                    }
			                }

			                if(util.Grid.getRowState(app, "grdCaseTrprList", nIdx) != cpr.data.tabledata.RowState.INSERTED) {
			                    if(!bCheckVal) {
			                        util.Msg.alert(app, "선택 대상자의 월마감이 완료되어 삭제가 불가능합니다.");
			                        return false;
			                    }
			                }
			            }
			        }
			    }
			}

