			                    app.lookup("dsCaseTrprList").setValue(cnt, "CASE_MNG_ODRNO"            , voReturnVal[i]["CASE_MNG_ODRNO"]);        //사례관리차수
			                    app.lookup("dsCaseTrprList").setValue(cnt, "CASE_BGNG_YMD"             , voReturnVal[i]["CASE_BGNG_YMD"]);         //사례시작일자
			                    app.lookup("dsCaseTrprList").setValue(cnt, "CASE_TRMN_YMD"             , voReturnVal[i]["CASE_TRMN_YMD"]);         //사례종결일자
